"use strict";(self.webpackChunk_=self.webpackChunk_||[]).push([["6178"],{7608(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>c,frontMatter:()=>o,contentTitle:()=>s,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"foundations/history-narrative","title":"History \u2014 Narrative","description":"The story of how we got here \u2014 key inflection points told with actual substance.","source":"@site/docs/foundations/history-narrative.md","sourceDirName":"foundations","slug":"/foundations/history-narrative","permalink":"/aible/docs/foundations/history-narrative","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4,"title":"History \u2014 Narrative","description":"The story of how we got here \u2014 key inflection points told with actual substance."},"sidebar":"mainSidebar","previous":{"title":"History \u2014 Timeline","permalink":"/aible/docs/foundations/history-timeline"},"next":{"title":"Neural Networks","permalink":"/aible/docs/foundations/neural-networks"}}'),a=n(4848),r=n(8453);let o={sidebar_position:4,title:"History \u2014 Narrative",description:"The story of how we got here \u2014 key inflection points told with actual substance."},s="History \u2014 Narrative",l={},d=[{value:"The founding bet (1950\u20131969)",id:"the-founding-bet-19501969",level:2},{value:"Expert systems and the first winter (1970\u20131987)",id:"expert-systems-and-the-first-winter-19701987",level:2},{value:"The quiet rebuilding (1986\u20132011)",id:"the-quiet-rebuilding-19862011",level:2},{value:"The eruption (2012\u20132017)",id:"the-eruption-20122017",level:2},{value:"Language becomes the medium (2018\u20132022)",id:"language-becomes-the-medium-20182022",level:2},{value:"The current era (2023\u2013present)",id:"the-current-era-2023present",level:2}];function h(e){let t={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"history--narrative",children:"History \u2014 Narrative"})}),"\n",(0,a.jsx)(t.p,{children:"The history of AI is not a steady march toward capability. It's a sequence of confident predictions, embarrassing failures, quiet rebuildings, and then eruptions that surprise even the people doing the work. Understanding the pattern helps you read the current moment more clearly."}),"\n",(0,a.jsxs)(t.p,{children:["For the dense chronological record, see ",(0,a.jsx)(t.a,{href:"/aible/docs/foundations/history-timeline",children:"History \u2014 Timeline"}),"."]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-founding-bet-19501969",children:"The founding bet (1950\u20131969)"}),"\n",(0,a.jsx)(t.p,{children:'The field begins with a philosophical question dressed as an engineering problem. Alan Turing\'s 1950 paper "Computing Machinery and Intelligence" asks whether machines can think and immediately sidesteps the question: he proposes the Imitation Game instead, reframing "thinking" as behavioral indistinguishability from a human in conversation. It\'s a clever move \u2014 it shifts the debate from metaphysics to measurement \u2014 but it embeds a confusion that the field still hasn\'t fully resolved. Behaving like something intelligent and being intelligent are not obviously the same.'}),"\n",(0,a.jsx)(t.p,{children:'The 1956 Dartmouth Conference that coined the term "Artificial Intelligence" was organized around a specific bet: that "every aspect of learning or any other feature of intelligence can in principle be so precisely described that a machine can be made to simulate it." The conference participants expected to make significant progress on the problem in one summer. They did not. But they named the field and set its ambitions, and those ambitions proved sticky.'}),"\n",(0,a.jsx)(t.p,{children:"The decade that followed was genuinely productive in narrow ways. LISP was invented. Expert systems like DENDRAL showed that encoding domain knowledge explicitly could produce expert-level performance on well-scoped tasks. ELIZA demonstrated that humans would project understanding onto any system that mirrored their words back \u2014 an observation about human psychology rather than machine capability, though this distinction was often lost."}),"\n",(0,a.jsxs)(t.p,{children:["The first hard wall arrived in 1969 when Minsky and Papert published ",(0,a.jsx)(t.em,{children:"Perceptrons"}),", proving mathematically that single-layer neural networks cannot learn XOR. The proof was correct. The interpretation \u2014 that neural networks were therefore a dead end \u2014 was not, but it was influential enough to divert funding away from neural approaches for years."]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"expert-systems-and-the-first-winter-19701987",children:"Expert systems and the first winter (1970\u20131987)"}),"\n",(0,a.jsx)(t.p,{children:"The dominant paradigm through the 1970s and most of the 1980s was symbolic AI: the idea that intelligence is manipulation of symbols according to rules, and that the rules can be written by hand. Expert systems \u2014 programs encoding the knowledge of domain specialists \u2014 became a substantial industry. XCON, deployed by Digital Equipment Corporation in 1980, saved the company an estimated $40 million per year configuring VAX computer orders. Dozens of similar systems followed in medicine, finance, and engineering."}),"\n",(0,a.jsx)(t.p,{children:'The problem became apparent around 1987: expert systems are brittle. They work precisely within their knowledge base and fail completely outside it. Maintaining them as domains evolved was expensive and slow. Rules written for one context couldn\'t transfer to adjacent contexts. The systems that had been confidently described as "nearly thinking" turned out to require constant manual intervention to stay accurate.'}),"\n",(0,a.jsx)(t.p,{children:"The AI industry, which had attracted substantial venture capital through the early 1980s, lost most of it by the end of the decade. What makes this period instructive: the failure wasn't from wrong ideas about what intelligence requires. Expert systems failed because encoding knowledge by hand doesn't scale. You can write rules for a narrow domain. You cannot write rules for everything a competent person knows. The field needed a different approach to acquiring knowledge \u2014 one that didn't require experts to articulate their expertise explicitly."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-quiet-rebuilding-19862011",children:"The quiet rebuilding (1986\u20132011)"}),"\n",(0,a.jsxs)(t.p,{children:["While the expert systems industry was collapsing, a smaller community was doing something different. In 1986, Rumelhart, Hinton, and Williams published the backpropagation paper in ",(0,a.jsx)(t.em,{children:"Nature"})," \u2014 not inventing the algorithm but framing it clearly enough that neural network researchers could use it. The key insight: if you can write a differentiable function, you can optimize it. If you can frame a learning problem as minimizing a differentiable loss, gradient descent will find the parameters that solve it."]}),"\n",(0,a.jsx)(t.p,{children:"Yann LeCun applied this to handwritten digit recognition with convolutional networks in the late 1980s. The results were good enough to deploy \u2014 AT&T used LeCun's network to read zip codes on mail. But it required weeks of training on hardware that cost hundreds of thousands of dollars. The approach was correct; the infrastructure wasn't ready."}),"\n",(0,a.jsx)(t.p,{children:"Throughout the 1990s and 2000s, kernel methods dominated machine learning benchmarks. SVMs had elegant theoretical foundations, worked well in practice, and didn't require the finicky training that neural networks did. A smaller group of neural network researchers worked on problems that the mainstream regarded as marginal \u2014 sequence modeling, speech, language. They were quietly accumulating the ideas that would matter later."}),"\n",(0,a.jsx)(t.p,{children:"Two subplots ran through this period. First, GPUs: originally designed for rendering video game graphics, they turned out to be extraordinarily well-suited for the parallel matrix multiplication that neural networks require. NVIDIA's CUDA (2007) made GPU programming accessible to researchers. The same networks that would have taken months to train in 2005 took days in 2010. Second, data: the internet was accumulating massive text corpora; Fei-Fei Li and her team spent three years assembling ImageNet \u2014 14 million labeled images. The training data needed to make large neural networks work was becoming available."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-eruption-20122017",children:"The eruption (2012\u20132017)"}),"\n",(0,a.jsx)(t.p,{children:"AlexNet in 2012 is the clean before/after. Alex Krizhevsky, Ilya Sutskever, and Geoffrey Hinton entered the ImageNet challenge with a deep convolutional network trained on two consumer gaming GPUs. They achieved a top-5 error rate of 15.3%. Second place was 26.2%. The gap was so large that the field didn't debate whether this was noise."}),"\n",(0,a.jsx)(t.p,{children:"Within two years, essentially every major company with a computer vision problem had switched to deep learning. The pattern accelerated: word2vec (2013) showed that word meanings could be encoded as geometric relationships in high-dimensional space \u2014 that you could compute with semantics using vector arithmetic. GANs (2014) showed that networks could generate realistic images by pitting a generator against a discriminator. Residual connections (2015) removed the practical depth limit on networks, enabling 150-layer architectures."}),"\n",(0,a.jsx)(t.p,{children:"AlphaGo in 2016 marked the end of the era when Go could be used as an argument that there are things machines fundamentally cannot do. The argument had been that Go's branching factor made brute-force search intractable, and that human intuition about \"good positions\" couldn't be encoded. AlphaGo learned that intuition from 30 million human games and then refined it through self-play. When it beat Lee Sedol 4\u20131, Go professionals described some of its moves as beautiful and occasionally alien."}),"\n",(0,a.jsx)(t.p,{children:'The transformer paper in 2017 \u2014 "Attention Is All You Need" \u2014 replaced recurrent connections with attention mechanisms and changed what was computationally tractable for language. Recurrent networks had to process text sequentially, one token at a time; attention processes the entire sequence simultaneously. It also removed the information bottleneck of squeezing long sequences through a single hidden state vector. The implications took another year to become fully apparent.'}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"language-becomes-the-medium-20182022",children:"Language becomes the medium (2018\u20132022)"}),"\n",(0,a.jsx)(t.p,{children:"BERT in 2018 demonstrated something that changed how the field thought about capability. You could train a model to predict masked words in Wikipedia text \u2014 a self-supervised task requiring no human annotation \u2014 and then fine-tune that model to achieve state-of-the-art performance on tasks ranging from question answering to sentiment analysis to named entity recognition. Transfer learning for language worked the way it had worked for images after AlexNet."}),"\n",(0,a.jsx)(t.p,{children:"GPT-3 in 2020 introduced a phenomenon that few had predicted: few-shot learning. Give the model three examples of the task in its context window, and it performs the task with no additional training. The model had learned, from predicting the next token on a large enough corpus, something like a general-purpose task adapter. It could write code, translate languages, answer questions about chemistry \u2014 not perfectly, but well enough to be useful, without being explicitly trained to do any of these things."}),"\n",(0,a.jsx)(t.p,{children:"This is the point where the field's self-understanding had to revise. The implicit assumption behind most AI research had been that different capabilities required different architectures and different training regimes. GPT-3 suggested that a sufficiently large model trained on sufficiently much text would develop a wide range of capabilities as emergent side effects."}),"\n",(0,a.jsx)(t.p,{children:"ChatGPT in 2022 added a layer that GPT-3 lacked: Reinforcement Learning from Human Feedback, making the model cooperative and helpful rather than merely completing text. The difference between a text completion engine and an assistant turns out to matter enormously for usability. ChatGPT reached 100 million users in two months."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"the-current-era-2023present",children:"The current era (2023\u2013present)"}),"\n",(0,a.jsx)(t.p,{children:"The distinguishing features of the current moment are scale, multimodality, and the beginning of agentic capability."}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Scale"}),' now produces qualitative differences. GPT-4 passes the bar exam \u2014 early reports claimed top 10% of human test-takers, though subsequent analysis suggests performance is closer to the median of actual law school graduates; the gap between test-taker and law-school-graduate populations makes the comparison contested. It solves competition mathematics problems that required doctoral-level reasoning to produce a few years ago. Whether this constitutes "real" reasoning or "sophisticated pattern matching" is a question philosophers of mind argue about; practitioners mostly observe that the outputs are useful and getting more so.']}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Multimodality"})," is no longer a research demo. GPT-4V, Gemini, and Claude process images, audio, and text within the same model. Stable Diffusion and its successors generate images from text descriptions on consumer hardware. The boundary between modalities is dissolving."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Agents"})," \u2014 models that can use tools, take multi-step actions, and interact with the world beyond generating text \u2014 are moving from research to production. Models browse the web, write and execute code, interact with APIs, and operate desktop interfaces. The reliability is imperfect; the trajectory is not."]}),"\n",(0,a.jsx)(t.p,{children:"What's genuinely unknown is where the current scaling approach runs into its limits. The standard critique \u2014 that large language models don't \"really understand\" and therefore can't generalize beyond their training distribution \u2014 has been made confidently before each capability jump and has so far underestimated what training on enough diverse data achieves. It may be correct eventually. The honest position is that nobody knows where the ceiling is."}),"\n",(0,a.jsx)(t.p,{children:"The pattern that repeats in both directions: confident claims about limits, followed by the limits being exceeded, followed by new claims about the next set of limits \u2014 but also confident claims about capabilities that turn out to be brittle, inconsistent, or illusory under careful evaluation. Staying calibrated means holding beliefs lightly about what these systems can and cannot do \u2014 updating when you see evidence, rather than fitting evidence to a prior conclusion in either direction."})]})}function c(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>s});var i=n(6540);let a={},r=i.createContext(a);function o(e){let t=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(r.Provider,{value:t},e.children)}}}]);